package app.realtimetranslator.session.entity;

import jakarta.persistence.*;
import lombok.Getter;
import lombok.NoArgsConstructor;
import lombok.Setter;

import java.time.Instant;
import java.util.UUID;

/**
 * JPA entity for the {@code meetings} table.
 * Each row represents one meeting session from start to end.
 *
 * {@code title} is nullable — it gets back-filled from the first summary
 * generated by GPT-4o (feature SUM001).
 */
@Entity
@Table(name = "meetings")
@Getter
@Setter
@NoArgsConstructor
public class MeetingEntity {

    @Id
    @GeneratedValue(strategy = GenerationType.UUID)
    private UUID id;

    @Column(name = "session_id", nullable = false, unique = true, length = 64)
    private String sessionId;

    @Column(name = "started_at", nullable = false)
    private Instant startedAt;

    // Set when session ends (WebSocket close or explicit CLOSE_SESSION).
    // Null while meeting is in progress.
    @Column(name = "ended_at")
    private Instant endedAt;

    // Auto-generated from summary content (SUM001). Null until first summary.
    @Column(name = "title")
    private String title;

    @Column(name = "source_lang", nullable = false, length = 8)
    private String sourceLang;

    @Column(name = "target_lang", nullable = false, length = 8)
    private String targetLang;

    // Updated on session end with final count from messages table.
    @Column(name = "total_messages")
    private int totalMessages;

    @Column(name = "created_at", nullable = false, updatable = false)
    private Instant createdAt;

    @PrePersist
    protected void onCreate() {
        // Default timestamps in Java rather than relying on DB default,
        // so the entity is consistent before and after persist.
        if (createdAt == null) {
            createdAt = Instant.now();
        }
        if (startedAt == null) {
            startedAt = Instant.now();
        }
    }
}
